       "text": "문 로드 이후 던전에서 Phantom Spirit을 잡아 Necroplasmic Beacon을 준비하거나, 최초 처치 전 Phantom Spirit 30마리 처치로 자연 소환할 수 있습니다. 2.1.0부터 자연 소환용 처치 수는 월드를 나가면 초기화됩니다. 프로비던스나 센티널 처치는 소환 필수 조건이 아닙니다."
