       "label": "엑소 메카 먼저",
       "text": "엑소 메카부터 잡으면 Exo Prism과 기체별 드롭을 얻습니다. Draedon's Forge와 Miracle Matter를 제작하면 Exoblade, Heavenly Gale, Vivid Clarity, Cosmic Immaterializer, Celestus 등의 직업별 엑소 제작 무기도 후보가 됩니다. 칼라미타스 처치는 이 제작 경로 자체의 필수 조건이 아닙니다."
